haracter/401305",false,false,false,false,false,false,false,"1",false,false,false,"120,0,1",1900,1014,380,1252,700,1770,2464,1252,703,1770,false,1,3387,5000,1499,4537,16000,16666,14333,4666,12960,false,10666,false,false,0},h)g[401306]=b({e[24034],401306,3,54,85,"「はい、どうぞ。このクリームを塗れば、怖いものが近づいてこなくなるから、今夜は安心して過ごせるよ。……え？　蚊が寄って来なくなるもの？　ちょっと待ってて、今すぐ虫よけの薬の研究を……！」",200013,2,"deco/character/yizhilaikong_WS",false,false,false,false,false,false,false,"1",false,false,"-30,0,1","240,-400,1","-30,0,1","-30,0,1","-30,0,1",1865,1045,380,967,223,2176,2294,967,734,2176},h)g[401401]=b({e[46057],401401,false,55,86,false,200014,false,"deco/character/mingzhiyingshu",302002,60,1,false,false,false,-228,false,false,false,false,false,false,false,false,"-40,650,0.91","-100,20,1","-60,20,1",false,false,false,"-100,30,1","-60,30,1",false,false,false,1901,856,430,1657,778,1034,3299,1657,778,1034,1053,"mingzhiyingshu"},h)g[401402]=b({e[11034],401402,1,4,87,"「少し休みましょうか。\nなにもせず、ただ一緒に座るだけ。どうでしょう？」",200014,1,"deco/character/mingzhiyingshu_0",302002,60,1915,895,447,995,594,2213,2801,995,618,2213,false,false,false,false,false,false,false,false,false,false,false,false,false,"mingzhiyingshu_0"},h)g[401403]=b({e[18034],401403,3,36,88,"「こんばんは。黒羽の使者・明智英樹が、お迎えに上がりました。僕と共にあの月光満ちる国へ参りましょう。貴方は断れない……そうでしょう？」",200014,2,"deco/character/mingzhiyingshu_WSJ",false,false,false,false,false,false,false,false,"2020-10-29 05:00:00+08",1995,920,361,939,595,2538,3434,939,600,2538,false,false,false,false,false,false,false,false,false,false,false,false,false,"mingzhiyingshu_ws"},h)g[401404]=b({e[21034],401404,2,47,89,"「今は風がそんなに強くないので、この辺りでしばらく休憩しましょうか。このペースなら、日が沈むまでに砂のお城が完成しそうです。思い描いた通りのお城になるといいですね。」",200014,2,"deco/character/mingzhiyingshu_YZ",false,false,false,false,false,false,false,false,false,false,false,"0,-90,1",1756,818,415,953,738,2649,2260,953,738,2649,1048,false,false,false,false,false,false,false,false,false,false,false,false,"mingzhiyingshu_xr"},h)g[401405]=b({e[9034],401405,11,56,90,"「ちょっと驚きですね、ここで会えるなんて。ええ、家族と一緒に来たんですが、ご覧の通りはぐれてしまいまして……。もし君も一人なら、これから一緒に花火を見に行きませんか？」",200014,2,"deco/character/mingzhiyingshu_YY",1836,860,380,767,697,3025,2865,829,697,2901,1113,false,false,false,false,false,false,false,false,false,false,false,false,"mingzhiyingshu_yy"},h)g[401406]=b({e[9044],401406,13,57,91,"「ああ……ついウトウトしてしまいました。サークルも順調で、悩み事も減ってきた、というのもあるでしょう。ただそれ以上に、君が傍にいる、というごくシンプルな理由で、気が緩んでしまったようです。」",200014,2,"deco/character/mingzhiyingshu_WQ",0,false,false,false,false,false,false,false,false,false,false,false,false,"mingzhiyingshu_wq"},h)